func cfKeyIs(t *port.Cells, from int32, to int32, k int32) int32 {
	// 1 when t[from, to) is key k: the whole of its name for a plain key, the start of the text for a prefix.
	var nl int32 = CkRows[k*5+4]
	var off int32 = CkRows[k*5+3]
	var shape int32 = CkRows[k*5+0]
	var i int32 = 0
	if (to - from) < nl {
		return 0
	}
	if (shape < shLimit) && ((to - from) != nl) {
		return 0
	}
	for i < nl {
		if port.CellsAt(t, from+i) != CkChars[off+i] {
			return 0
		}
		i += 1
	}
	return 1
}

