func cfNum(t *port.Cells, from int32, to int32, c *enctx.Cfg) int32 {
	// A decimal with an optional sign, as Rust's i32 parse reads one, but -2147483648 is out of range here. 1 with the value in `num`, else 0.
	var i int32 = from
	var neg int32 = 0
	var v int32 = 0
	if i < to {
		if port.CellsAt(t, i) == 45 {
			neg = 1
			i += 1
		} else if port.CellsAt(t, i) == 43 {
			i += 1
		}
	}
	if i >= to {
		return 0
	}
	for i < to {
		var ch int32 = port.CellsAt(t, i)
		if (ch < 48) || (ch > 57) {
			return 0
		}
		if (v > 214748364) || ((v == 214748364) && ((ch - 48) > 7)) {
			return 0
		}
		v = (v * 10) + (ch - 48)
		i += 1
	}
	if neg == 1 {
		v = 0 - v
	}
	c.Num = v
	return 1
}

