func cfOne(t *port.Cells, vf int32, vt int32) int32 {
	// 1 when the value is exactly `1`.
	if (vt - vf) != 1 {
		return 0
	}
	if port.CellsAt(t, vf) == 49 {
		return 1
	}
	return 0
}

func cfApply(t *port.Cells, k int32, kf int32, ke int32, vf int32, vt int32, c *enctx.Cfg) int32 {
	// The line t[kf, ke) = t[vf, vt) for key k: 1, or 0 with the sentence in `msg`.
	var shape int32 = CkRows[k*5+0]
	if shape == shStr {
		port.CellsDrop(c.Lcl, 0)
		c.Haveloc = 1
		var i int32 = vf
		for i < vt {
			port.CellsPush(c.Lcl, port.CellsAt(t, i))
			i += 1
		}
		return 1
	}
	if shape == shNum {
		if cfNum(t, vf, vt, c) == 0 {
			cfFailNum(t, kf, ke, vf, vt, c)
			return 0
		}
		if (c.Num < CkRows[k*5+1]) || (c.Num > CkRows[k*5+2]) {
			cfFailRange(t, kf, ke, CkRows[k*5+1], CkRows[k*5+2], c)
			return 0
		}
		cfSetNum(c, k, c.Num)
		return 1
	}
	if shape == shEnum {
		var code int32 = cfWord(t, vf, vt, k)
		if code < 0 {
			cfFailEnum(k, c)
			return 0
		}
		cfSetWord(c, k, code)
		return 1
	}
	if shape == shFlag {
		cfSetFlag(c, k, cfOne(t, vf, vt))
		return 1
	}
	if shape == shLimit {
		var kind int32 = CfLimitFind(t, kf+CkRows[k*5+4], ke)
		if kind < 0 {
			port.TextAscii(c.Msg, "no limit named ")
			cfPutSpan(t, kf+CkRows[k*5+4], ke, c)
			return 0
		}
		if cfNum(t, vf, vt, c) == 0 {
			cfFailNum(t, kf, ke, vf, vt, c)
			return 0
		}
		if (c.Num < limits.LmRows[kind*6+1]) || (c.Num > limits.LmRows[kind*6+2]) {
			cfFailRange(t, kf, ke, limits.LmRows[kind*6+1], limits.LmRows[kind*6+2], c)
			return 0
		}
		port.CellsPush(c.Lims, kind)
		port.CellsPush(c.Lims, c.Num)
		return 1
	}
	var nf int32 = kf + CkRows[k*5+4]
	var q int32 = 0
	port.CellsPush(c.Prod, ke-nf)
	port.CellsPush(c.Prod, vt-vf)
	q = nf
	for q < ke {
		port.CellsPush(c.Prod, port.CellsAt(t, q))
		q += 1
	}
	q = vf
	for q < vt {
		port.CellsPush(c.Prod, port.CellsAt(t, q))
		q += 1
	}
	return 1
}

func cfLine(t *port.Cells, from int32, to int32, c *enctx.Cfg) int32 {
	// One non-empty line: 1, or 0 with the sentence in `msg`.
	var eq int32 = from
	for (eq < to) && (port.CellsAt(t, eq) != 61) {
		eq += 1
	}
	if eq == to {
		port.TextAscii(c.Msg, "option \"")
		cfPutSpan(t, from, to, c)
		port.TextAscii(c.Msg, "\" has no value")
		return 0
	}
	var k int32 = CfKeyFind(t, from, eq)
	if k < 0 {
		port.TextAscii(c.Msg, "unknown option ")
		cfPutSpan(t, from, eq, c)
		return 0
	}
	return cfApply(t, k, from, eq, eq+1, to, c)
}

func CfParse(t *port.Cells, c *enctx.Cfg) int32 {
	// Fill `c` from the options text `t` (code points): the defaults, then each line. Answers 0, or 1 with the sentence in `(fd c msg)`.
	CfDefaults(c)
	var n int32 = port.CellsLen(t)
	var at int32 = 0
	for at < n {
		var le int32 = at
		var hi int32 = at
		for (le < n) && (port.CellsAt(t, le) != 10) {
			le += 1
		}
		hi = le
		if (hi > at) && (port.CellsAt(t, hi-1) == 13) {
			hi -= 1
		}
		if hi > at {
			if cfLine(t, at, hi, c) == 0 {
				return 1
			}
		}
		at = le + 1
	}
	return 0
}

func CfIsKey(t *port.Cells, from int32, to int32) int32 {
	// 1 when t[from, to) names a key of the grammar (a driver asks it of `--NAME=`).
	if CfKeyFind(t, from, to) < 0 {
		return 0
	}
	return 1
}
